def rnd_string(string_length=8):
    hash_object = hashlib.md5(str(uuid.uuid4()).encode())
    hash_ascii = hash_object.hexdigest()
    return hash_ascii[:string_length].lower()


class ShellCommandHandler:

    def __init__(self,
                 logger,
                 command_id: Optional[str] = None,
                 nats_communicator: Optional[NatsCommunicator] = None,
                 merge_data: Optional[dict] = None) -> None:
        self.id = command_id or rnd_string()
        # Identify log messages belonging to this command by having command ID included for each message
        self.logger = logger
        self.command = ""
        self.command_output = ""
        self.params = {}
        self.nats_communicator = nats_communicator
        self.output_stream_subjects = []
        self.output_merge = merge_data if isinstance(merge_data, dict) else {}
        self.iperf_number_of_threads = None

    def get_cmd_args(self):
        """
        Parse command arguments to dict
        Cmd e.g. iperf --udp --bandwidth --interval 1  --format m
        Output:
            {'client': 'ipX', 'interval': 1, 'time': 40, 'udp': True, 'format': 'm'}
        """
        command_args = {}
        try:
            before_args = self.command.split("-")[0].strip()
            command_args.update({"cmd": before_args})
            iperf_cmd_iter = re.finditer(
                r'(?:-{1,2}|\/)(?P<name>\w+)(?:[=:]?|\s+)(?P<value>[^-\s"][^"]*?|"[^"]*")?(?=\s+[-\/]|$)',
                self.command,
            )
            for m in iperf_cmd_iter:
                val, key = m.groups()
                if val is not None:
                    if key is None:
                        key = True
                    elif isinstance(key, str) and key.isdigit():
                        key = int(key)
                    command_args.update({f"cmdArg.{val}": key})
        except Exception as exc:
            self.logger.debug(f"Failed to parse command arguments: {self.command}", exc)
        return command_args

    async def handle_cmd_output(self, output):  # noqa: C901
        try:
            # cmd e.g. iperf --udp --bandwidth --interval 1  --format m
            pattern = r"\[SUM\].*?(\d+\.\d+[ ][MKG]?bits/sec|\d+[ ][MKG]?bits/sec)" \
                if self.iperf_number_of_threads and self.iperf_number_of_threads > 1 \
                else r"\d+\.\d+[ ][MKG]?bits/sec|\d+[ ][MKG]?bits/sec"
            iperf_matches = re.findall(pattern, output)
            if iperf_matches:
                throughput_str = iperf_matches[0]
                throughput = float(re.findall(r"\d+\.\d+|\d+", throughput_str)[0])
                if "Mbits/sec" in throughput_str:
                    ...  # Already in Mbits/sec
                elif "Gbits/sec" in throughput_str:
                    throughput *= 1000  # Convert Gbits/sec to Mbits/sec
                elif "Kbits/sec" in throughput_str:
                    throughput /= 1000  # Convert Kbits/sec to Mbits/sec
                elif "bits/sec" in throughput_str:
                    throughput /= 1000000  # Convert bits/sec to Mbits/sec
                self.params["command"] = self.command
                line_vals = {
                    "dlThroughput" if "command" in self.params["type"] else "ulThroughput": throughput,
                    "output": output.strip()
                }
                measurement = {
                    "ue": line_vals, **self.get_cmd_args(), **self.params,
                    "command": self.command,
                    "device_id": getattr(self, "device_id", "")
                }
                await self.handle_cmd_output_common(measurement)
        except Exception as e:
            self.logger.error(f"Failed to handle cmd output: {output}", e)

    async def handle_cmd_output_common(self, measurement):
        if self.output_merge:
            dict_merge(measurement, self.output_merge)
        if self.nats_communicator and self.output_stream_subjects:
            for subject in self.output_stream_subjects:
                if self.nats_communicator.nc:
                    self.logger.info(f"Sending measurement to {self.nats_communicator.nats_server}, {subject=}, "
                                     f"{measurement=}")
                    await self.nats_communicator.nc.publish(subject, json.dumps(measurement).encode())


class DeviceCommandHandler(ShellCommandHandler):
    """
    Handles commands where iperf server is running on the controller.
    :subject: device.ueservice.{ue_service_id}.meas.iperf.ul
    """
    def __init__(self, logger, command_id, device_id, agent_id, agent_address, nc, merge_data=None):
        super().__init__(logger=logger,
                                                   command_id=command_id,
                                                   nats_communicator=nc,
                                                   merge_data=merge_data)
        self.params["type"] = "command"
        self.agent_address = agent_address
        self.agent_id = agent_id
        self.device_id = device_id

    async def handle_cmd_output(self, output, subject=None):
        self.command_output += output
        if output:
            data = {
                "command_id": self.output_merge.get("command_id") or self.id,
                "device_id": self.device_id.get("id") if isinstance(self.device_id, dict) else self.device_id,
                "agent_id": self.agent_id,
                "command": self.command,
                "command_output": output,
            }
            item_data = {
                "subject": subject if subject else self.nats_communicator.NATS_PUBLISH_CHANNEL_CMD_OUT_AGENT,
                "payload": data,
            }
            if self.nats_communicator:
                await self.nats_communicator.queue.put(item=item_data)
            await super().handle_cmd_output(output)


class ControllerCommandHandler(ShellCommandHandler):
    """
    Handles commands that are executed on the UE_PC.
    :subject: device.ueservice.{ue_service_id}.meas.iperf.dl
    """
    def __init__(self, logger, command_id=None, nc=None, merge_data=None):
        super().__init__(logger=logger,
                                                       command_id=command_id,
                                                       nats_communicator=nc,
                                                       merge_data=merge_data)
        self.params["type"] = "controller"

    async def handle_cmd_output(self, output, subject=None):
        self.command_output += output
        if output:
            data = {
                "ue_service_id": self.output_merge.get("ue_service_id") or UE_SERVICE_CTRL_ID,
                "command_id": self.id,
                "command": self.command,
                "command_output": output,
            }
            item_data = {
                "subject": subject if subject else self.nats_communicator.NATS_PUBLISH_CHANNEL_CMD_OUT_SERVICE_CTRL,
                "payload": data,
            }
            if self.nats_communicator:
                await self.nats_communicator.queue.put(item=item_data)
            await super().handle_cmd_output(output)


def dict_merge(one, *args):
    """
    Recursively merge dictionaries.
    :param one: dict
    :param args: list of dicts
    """
    for two in args:
        for k, v in two.items():
            if k in one and isinstance(one[k], dict) and isinstance(two[k], Mapping):
                dict_merge(one[k], two[k])
            else:
                one[k] = two[k]
